const attempt=(k,action)=>{try{t.reactions=[{actions:[action],trigger:{type:'ON_CLICK'}}];tries[k]='ok '+JSON.stringify(t.reactions).substring(0,200);}catch(e){tries[k]=e.message.substring(0,200);}};
attempt('instant',{type:'NODE',destinationId:pr.id,navigation:'NAVIGATE',transition:{type:'INSTANT'}});
t.reactions=[];
attempt('smart',{type:'NODE',destinationId:pr.id,navigation:'NAVIGATE',transition:{type:'SMART_ANIMATE',duration:300,easing:{type:'EASE_OUT'},matchLayers:[]}});
t.remove();
return tries;

const pr=figma.currentPage.children.find(x=>x.name==='10_Profile');
const wrap=figma.createFrame();wrap.resize(100,40);wrap.x=0;wrap.y=-200;figma.currentPage.appendChild(wrap);
const t=figma.createText();t.characters='x';wrap.appendChild(t);
let err=null;
try{t.reactions=[{actions:[{type:'NODE',destinationId:pr.id,navigation:'NAVIGATE',transition:{type:'SMART_ANIMATE',duration:300,easing:{type:'EASE_OUT'}}}],trigger:{type:'ON_CLICK'}}];}catch(e){err=e.message.substring(0,200);}
const got=JSON.stringify(t.reactions).substring(0,150);
wrap.remove();
return {err,got};

const frames={};
for(const f of figma.currentPage.children){if(/^\d\d_/.test(f.name))frames[f.name]=f;}
function S(hex,o=1){const n=parseInt(hex.slice(1),16);return[{type:'SOLID',color:{r:(n>>16&255)/255,g:(n>>8&255)/255,b:(n&255)/255},opacity:o}];}
let ok=0;const fail=[];
function nav(fromName,toName,targets){
const from=frames[fromName],to=frames[toName];if(!from||!to){fail.push(fromName+'>'+toName);return;}
const fb=from.absoluteBoundingBox, dest=to.id;
for(const t of targets){
const n=from.findOne(x=>x.name===t);
if(!n){fail.push(fromName+':'+t);continue;}
let holder=n;
if(n.type==='INSTANCE'){
const nb=n.absoluteBoundingBox;
const ov=figma.createRectangle();ov.resize(Math.max(nb.width,8),Math.max(nb.height,8));ov.fills=S('#FFFFFF',0.001);ov.name='Hit_'+t;
const parent=(n.parent&&n.parent.type!=='INSTANCE')?n.parent:from;
parent.appendChild(ov);
ov.x=nb.x-fb.x;ov.y=nb.y-fb.y;
holder=ov;}
try{holder.reactions=[{actions:[{type:'NODE',destinationId:dest,navigation:'NAVIGATE',transition:{type:'SMART_ANIMATE',duration:300,easing:{type:'EASE_OUT'}}}],trigger:{type:'ON_CLICK'}}];ok++;}catch(e){fail.push(fromName+':'+t+':'+e.message.substring(0,60));}
}}
