let count=0;const names=[];
for(const f of figma.currentPage.children){if(/^\d\d_/.test(f.name)){
for(const n of f.findAll(x=>x.reactions&&x.reactions.length)){count++;names.push(f.name+'/'+n.name);}}}
return {count,names:names.join(',')};
